{
  "гриб": "Amanita citrina (ложная бледная поганка, false death cap)",
  "состав": [
    {
      "вещество": "α-аманитин (α-amanitin)",
      "содержание": "≈ 1–2 мг/г сухого веса",
      "влияние": "Необратимо ингибирует РНК-полимеразу II, вызывая клеточную гибель, преимущественно печёночного и почечного parenchyma, и является главной причиной тяжёлых отравлений со смертельным исходом."
    },
    {
      "вещество": "β-аманитин (β-amanitin)",
      "содержание": "≈ 0,2–0,5 мг/г сухого веса",
      "влияние": "Оказывает то же действие на РНК-полимеразу II, что и α-аманитин, но с меньшей аффинностью; усиливает общий токсический эффект."
    },
    {
      "вещество": "γ-аманитин (γ-amanitin)",
      "содержание": "< 0,1 мг/г сухого веса (следовые количества)",
      "влияние": "Ингибирует РНК-полимеразу II в значительно меньшей степени, чем α- и β-аманитины; клиническое значение незначительно."
    },
    {
      "вещество": "Эпиманин (epimanin)",
      "содержание": "неизвестно (следовые количества)",
      "влияние": "Диастереомер α-аманитина с более слабым связыванием с РНК-полимеразой II; токсичность существенно ниже, чем у α-аманитина."
    },
    {
      "вещество": "Иботеновая кислота (ibotenic acid)",
      "содержание": "≈ 50–150 мг/кг сухого веса",
      "влияние": "Агонист глутаматных (NMDA) рецепторов, вызывает возбуждение ЦНС, судороги и дезориентацию; при длительном хранении частично декарбоксилируется в мусцимол."
    },
    {
      "вещество": "Мусцимол (muscimol)",
      "содержание": "неизвестно (следовые количества)",
      "влияние": "Агонист ГАМК-А рецепторов, вызывает седацию, миоклонус и спутанность сознания."
    },
    {
      "вещество": "Хитин и β-глюканы (составные полисахариды клеточных стенок)",
      "содержание": "≈ 10–15 % сухого веса",
      "влияние": "Практически не перевариваются человеком, не оказывая выраженного фармакологического эффекта; при пищеварении могут усиливать осмотическую нагрузку в кишечнике."
    },
    {
      "вещество": "Белки (общий белковый комплекс)",
      "содержание": "≈ 20–30 % сухого веса",
      "влияние": "Служат источником аминокислот при переваривании; сами по себе токсичны не являются, но могут содержать аллергены для чувствительных лиц."
    }
  ]
}

{
  "гриб": "Amanita caesarea (Цезарская шляпочница / Гриб царский)",
  "состав": [
    {
      "вещество": "Белки (в сумме)",
      "содержание": "≈ 3,0–4,5 % сырой массы",
      "влияние": "Полноценный источник незаменимых аминокислот, усваиваемый организмом человека как обычный пищевой белок."
    },
    {
      "вещество": "Хитин (полисахарид стенок клеток)",
      "содержание": "≈ 5–8 % сухой массы",
      "влияние": "Вещество неперевариваемое, однако стимулирует перистальтику кишечника и поддерживает микробиом как пребиотик."
    },
    {
      "вещество": "Липиды (олеиновая, линолевая, арахидоновая кислоты)",
      "содержание": "≈ 0,5–1,5 % сырой массы",
      "влияние": "Богатые омега-3 и омега-6 жирными кислотами, способствуют нормализации липидного профиля крови."
    },
    {
      "вещество": "Эргостерол (провитамин D₂)",
      "содержание": "≈ 50–100 мг/кг сырой массы",
      "влияние": "Под действием УФ-излучения превращается в витамин D₂, участвующий в обмене кальция и формировании костей."
    },
    {
      "вещество": "Свободная глутаминовая кислота",
      "содержание": "≈ 1–2 % сырой массы",
      "влияние": "Обеспечивает характерный умами-вкус и служит нейромедиатором ЦНС в малых дозах."
    },
    {
      "вещество": "Калий (K⁺)",
      "содержание": "≈ 3 000–5 000 мг/кг сырой массы",
      "влияние": "Поддерживает водно-электролитный баланс и нормальную работу сердечно-сосудистой системы."
    },
    {
      "вещество": "Фосфор (P)",
      "содержание": "≈ 1 000–1 500 мг/кг сырой массы",
      "влияние": "Участвует в энергетическом обмене (АТФ), формировании костей и зубов."
    },
    {
      "вещество": "Рибофлавин (витамин B₂)",
      "содержание": "≈ 1–3 мг/кг сырой массы",
      "влияние": "Кофактор оксидоредуктаз, поддерживает зрение, функцию кожи и нервной ткани."
    },
    {
      "вещество": "Ниацин (витамин B₃ / никотинамид)",
      "содержание": "≈ 5–15 мг/кг сырой массы",
      "влияние": "Входит в состав НАД⁺/НАДН, участвует в клеточном дыхании и синтезе ДНК."
    },
    {
      "вещество": "Селен (Se)",
      "содержание": "≈ 20–60 мкг/кг сырой массы",
      "влияние": "Составной элемент глутатион-пероксидазы, обеспечивает антиоксидантную защиту клеток."
    }
  ]
}
